```ts
import type { GeospatialCamera } from "@babylonjs/lite";

/**
 * Sets the camera's pitch (radians, 0 = looking straight down) without
 * changing its yaw, radius (zoom) or centre.
 *
 * The pitch limits are widened and the zoom-dependent pitch cap is disabled,
 * so the requested tilt is not clamped at the current zoom or at zooms the
 * app moves to later.
 */
export function tiltGlobeCamera(camera: GeospatialCamera, pitch: number): void {
    if (!Number.isFinite(pitch)) {
        throw new RangeError("pitch must be a finite number");
    }

    const limits = camera.limits;
    limits.pitchDisabledRadiusScale = null;
    limits.pitchMin = Math.min(limits.pitchMin, pitch);
    limits.pitchMax = Math.max(limits.pitchMax, pitch);

    const yaw = camera.yaw;
    const radius = camera.radius;
    const center = { x: camera.center.x, y: camera.center.y, z: camera.center.z };

    camera._setOrientation(yaw, pitch, radius, center);
}
```

I wrote the file's content here but could not run or compile it, since the library is not on this machine and I did not write it to disk in this session. The function sets the pitch limits so the requested pitch is allowed at any zoom, then sets the orientation with the current yaw, radius and centre.

I am not sure of several things:
- I assumed `pitchDisabledRadiusScale = null` removes the zoom-dependent pitch cap. The type doesn't say what null means.
- I used `_setOrientation`, which is on the public interface, rather than the exported `setGeospatialOrientation`. I don't know whether either one applies the limits or clamps the centre.
- I assumed the library's pitch 0 is straight down, as your spec describes.
- Widening the camera's pitch limits is a lasting change to that camera, which the rest of the app will see.
